// Navbar Injection Script
// This script adds the Advanced Metrics tab to existing dashboard navbars

const injectionScript = `
<script>
// Advanced Metrics Navbar Injection
(function() {
    'use strict';

    function injectAdvancedMetricsNavItem() {
        // Find the navbar
        const navbar = document.querySelector('.navbar-nav');
        if (!navbar) {
            console.log('Navbar not found, retrying in 500ms...');
            setTimeout(injectAdvancedMetricsNavItem, 500);
            return;
        }

        // Check if already injected
        if (navbar.querySelector('a[href="/metrics"]')) {
            console.log('Advanced Metrics nav item already exists');
            return;
        }

        // Create the Advanced Metrics nav item
        const metricsNavItem = document.createElement('li');
        metricsNavItem.className = 'nav-item';

        const metricsLink = document.createElement('a');
        metricsLink.className = 'nav-link';
        metricsLink.href = '/metrics';
        metricsLink.innerHTML = '⚡ Advanced Metrics';

        // Add hover effects
        metricsLink.style.transition = 'all 0.3s';
        metricsLink.addEventListener('mouseenter', function() {
            this.style.color = '#aa44ff';
            this.style.background = 'rgba(170,68,255,0.1)';
        });
        metricsLink.addEventListener('mouseleave', function() {
            this.style.color = '#aaa';
            this.style.background = 'transparent';
        });

        metricsNavItem.appendChild(metricsLink);
        navbar.appendChild(metricsNavItem);

        console.log('✅ Advanced Metrics nav item injected successfully');

        // Add notification
        showInjectionNotification();
    }

    function showInjectionNotification() {
        const notification = document.createElement('div');
        notification.innerHTML = '⚡ Advanced Metrics navigation added!';
        notification.style.cssText = \`
            position: fixed;
            top: 20px;
            right: 20px;
            background: linear-gradient(135deg, #aa44ff, #8833cc);
            color: white;
            padding: 10px 20px;
            border-radius: 8px;
            box-shadow: 0 4px 12px rgba(170,68,255,0.3);
            font-size: 14px;
            font-weight: bold;
            z-index: 10000;
            animation: slideIn 0.3s ease-out;
        \`;

        // Add animation
        const style = document.createElement('style');
        style.textContent = \`
            @keyframes slideIn {
                from { transform: translateX(100%); opacity: 0; }
                to { transform: translateX(0); opacity: 1; }
            }
            @keyframes slideOut {
                from { transform: translateX(0); opacity: 1; }
                to { transform: translateX(100%); opacity: 0; }
            }
        \`;
        document.head.appendChild(style);

        document.body.appendChild(notification);

        // Auto-remove after 3 seconds
        setTimeout(() => {
            notification.style.animation = 'slideOut 0.3s ease-in';
            setTimeout(() => {
                if (notification.parentNode) {
                    notification.parentNode.removeChild(notification);
                }
            }, 300);
        }, 3000);
    }

    // Initialize injection when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injectAdvancedMetricsNavItem);
    } else {
        injectAdvancedMetricsNavItem();
    }

    // Also try injection after a delay to handle dynamic content
    setTimeout(injectAdvancedMetricsNavItem, 1000);
    setTimeout(injectAdvancedMetricsNavItem, 3000);

})();
</script>
`;

